<script setup lang="ts">
import {ChevronDown, ChevronUp, Copy, Eye, EyeOff, Lock, LockOpen, Plus, Trash2, UserRoundPlus} from 'lucide-vue-next';
import type {RasterLayer} from '../model/canvas-types';
const props=defineProps<{layers:RasterLayer[];activeId?:string;costumeLayerIds:Set<string>;previewUrl:(layer:RasterLayer)=>string}>();
const emit=defineEmits<{select:[id:string];toggleVisible:[id:string];toggleLock:[id:string];rename:[id:string,name:string];duplicate:[];remove:[];blank:[];toggleCostume:[id:string];move:[id:string,direction:-1|1];opacity:[id:string,value:number]}>();
</script>
<template><section class="resource-panel"><div class="resource-panel__actions"><button title="新建空白图层" aria-label="新建空白图层" @click="emit('blank')"><Plus :size="16"/></button><button title="复制图层" aria-label="复制图层" @click="emit('duplicate')"><Copy :size="16"/></button><button title="删除图层" aria-label="删除图层" @click="emit('remove')"><Trash2 :size="16"/></button></div><div class="layer-list" role="listbox" aria-label="图层"><article v-for="(layer,reverseIndex) in [...props.layers].reverse()" :key="layer.id" class="layer-item"><div class="layer-row" :class="{'is-active':layer.id===props.activeId}" role="option" :aria-selected="layer.id===props.activeId" tabindex="0" @click="emit('select',layer.id)" @keydown.enter="emit('select',layer.id)"><button :title="layer.visible?'隐藏图层':'显示图层'" :aria-label="layer.visible?'隐藏图层':'显示图层'" @click.stop="emit('toggleVisible',layer.id)"><Eye v-if="layer.visible" :size="15"/><EyeOff v-else :size="15"/></button><div class="layer-row__thumb" aria-hidden="true"><img :src="props.previewUrl(layer)" alt=""/></div><input :value="layer.name" aria-label="图层名称" @click.stop @change="emit('rename',layer.id,($event.target as HTMLInputElement).value)"/><button :title="layer.locked?'解锁图层':'锁定图层'" :aria-label="layer.locked?'解锁图层':'锁定图层'" @click.stop="emit('toggleLock',layer.id)"><Lock v-if="layer.locked" :size="15"/><LockOpen v-else :size="15"/></button><button :class="{'is-marked':props.costumeLayerIds.has(layer.id)}" title="加入或移出造型队列" aria-label="加入或移出造型队列" @click.stop="emit('toggleCostume',layer.id)"><UserRoundPlus :size="15"/></button></div><div class="layer-metadata"><label>透明度 <input type="range" min="0" max="100" :value="Math.round(layer.opacity*100)" :aria-label="layer.name+'透明度'" @change="emit('opacity',layer.id,Number(($event.target as HTMLInputElement).value)/100)"/><span>{{Math.round(layer.opacity*100)}}%</span></label><div><button title="上移图层" aria-label="上移图层" :disabled="reverseIndex===0" @click="emit('move',layer.id,1)"><ChevronUp :size="14"/></button><button title="下移图层" aria-label="下移图层" :disabled="reverseIndex===props.layers.length-1" @click="emit('move',layer.id,-1)"><ChevronDown :size="14"/></button></div></div></article><p v-if="!props.layers.length" class="resource-empty">导入图片后会显示图层</p></div></section></template>
